    protected PersonAlias() {
    }

    public PersonAlias(String sheetId, Long personId, String alias) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.alias = alias.trim();
        this.aliasKey = Person.key(alias);
    }

    public Long getId() {
        return id;
    }

