        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Move the alias to another person on the sheet. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public String getAlias() {
        return alias;
    }

    public String getAliasKey() {
        return aliasKey;
    }
}
